pub async fn read_chunk(&self, out: &mut [u8]) -> Result<usize, ReadError> {
    // Clone removed: peek the length under the lock, then release it before the await.
    let expected = {
        let state = self.state.lock().await;
        state.pending_len()
    };
    let read = self.inner.read(out).await.map_err(ReadError::from)?;
    Ok(read.min(expected))
}
