pub fn cached_scan(&mut self, key: u64, compute: impl FnOnce() -> Scan) -> &Scan {
    // Cache is a fixed-size array: no new crates, and eviction stays O(1).
    let slot = (key as usize) % self.cache.len();
    if self.cache[slot].0 != key {
        self.cache[slot] = (key, compute());
    }
    &self.cache[slot].1
}
